loop = (now) => {
  const raw = (now - this.lastFrame)/1000 || 0.016;
  this.lastFrame = now;
  const dt = Math.min(0.05, Math.max(0, raw));
  if (!this.paused) {
    this.time += dt;
    this.updateGame(dt);
  }
  this.renderer.render(this, this.paused?0:dt);
  requestAnimationFrame(this.loop);
}
```
