      if (!targets.length) targets = this.balls.filter(b => !b.potted && b.type === 'eight');
    }
    if (!targets.length) return this.aim || 0;
    const nearest = targets.sort((a, b) => Math.hypot(a.x - cue.x, a.y - cue.y) - Math.hypot(b.x - cue.x, b.y - cue.y))[0];
