    const grd = ctx.createRadialGradient(game.cue.x, game.cue.y, 2, game.cue.x, game.cue.y, 56);
    grd.addColorStop(0, `rgba(255,255,255,${pulse})`);
    grd.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = grd;
